            layer=newlayer
            pars=newpars
            if j%2==0:
                same+=len(layer)
        bipartite=same*(n-same)
        info=countchildren(neigh,0,[None]*n)[1]
        dist=0
        for guy in info:
            if guy!=None:
               dist+=(guy+1)*(n-guy-1)
        print((dist+bipartite)//2)
    sys.setrecursionlimit(2097152)
    threading.stack_size(134217728)
    main_thread=threading.Thread(target=main)
    main_thread.start()
    main_thread.join()

